// src/motion.ts
var DURATION_VAR = "--ld-duration";
var PLAY_STATE_VAR = "--ld-play-state";
var SIZE_VAR = "--ld-size";
var STEP_VAR = "--ld-step";
var DEFAULT_SIZE = 20;
var SIZE = `var(${SIZE_VAR}, ${DEFAULT_SIZE}px)`;
var SPINNER_MOTION = {
  arc: 800,
  atom: 1e3,
  blocks: 1300,
  "bouncing-dots": 500,
  cascade: 1500,
  "circular-dots": 800,
  classic: 1200,
  "classic-v2": 800,
  clock: 1200,
  comet: 700,
  compass: 500,
  dual: 1e3,
  eclipse: 1200,
  flip: 1200,
  gather: 1600,
  leap: 1800,
  "linear-dots": 900,
  loading: 1e3,
  morph: 1200,
  orbit: 750,
  pulse: 1200,
  radar: 1500,
  ring: 800,
  ripple: 1200,
  slide: 2400,
  snake: 1400,
  swirl: 1200,
  trace: 1200,
  wave: 900
};
function duration(name) {
  return `var(${DURATION_VAR}, ${SPINNER_MOTION[name]}ms)`;
}
function stagger(name, count) {
  return `calc(${duration(name)} * (var(${STEP_VAR}) - ${count}) / ${count})`;
}
var PLAY_STATE = `var(${PLAY_STATE_VAR}, running)`;
function animation(name, keyframes, timing) {
  const runs = [keyframes].flat().map((frames) => `${frames} ${duration(name)} ${timing} infinite`);
  return `animation: ${runs.join(", ")};
  animation-play-state: ${PLAY_STATE};`;
}

export {
  DURATION_VAR,
  PLAY_STATE_VAR,
  SIZE_VAR,
  STEP_VAR,
  DEFAULT_SIZE,
  SIZE,
  SPINNER_MOTION,
  duration,
  stagger,
  PLAY_STATE,
  animation
};
